left join (
  select
 		OwnerUserId,
		count(*) as PostsCreatedInMonth
	from Posts 
	where OwnerUserId is not NULL and CreationDate >= now() - interval '3 month'
	group by OwnerUserId
) cnt On cnt.OwnerUserId = u.Id)
